"""Bounded read of HDB's observed first results-category page, using its frontend."""
import base64,datetime,hashlib,json,pathlib,re,subprocess,urllib.parse
B=pathlib.Path('data/initialization-08b-remediation-work/targeted-indexes')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
parent=B/'HDB-required-current-results-page.body';receipt=json.loads(parent.with_suffix('.json').read_text());assert receipt['httpStatus']=='200' and receipt['curlExit']==0 and sha(parent)==receipt['bodySha256']
ssr=json.loads(re.search(r'<script id="__NEXT_DATA__"[^>]*>(.*?)</script>',parent.read_text(),re.S)[1]);param=ssr['props']['pageProps']['param'];assert param['lang']=='en' and param['slug_detail']=='bao-cao-ket-qua-hoat-dong-kinh-doanh-quy'
client=B/'HDB-public-report-client.body';assert 'pageSize:6,isExcludeNews:!0' in client.read_text() and 'slug_category:r.productActive' in client.read_text()
app=B/'HDB-public-report-dependency-0.js';text=app.read_text();assert 'ac(t.payload.local,t.payload.params)' in text and '"/investors/new/category/post"' in text
params={'slug_category':param['slug_detail'],'page':'1','pageSize':'6','isExcludeNews':'true'};url='https://hdbank.com.vn/api/investors/new/category/post?'+urllib.parse.urlencode(params);body=B/'HDB-required-current-results-first-page.body';assert not body.exists();started=datetime.datetime.now(datetime.timezone.utc).isoformat()
r=subprocess.run(['curl','--fail','--location','--silent','--show-error','--cacert','/etc/ssl/cert.pem','--max-time','45','--header','local: en','--header','Content-Type: application/json','--header','Cache-Control: max-age=600','--header','device_type: 0','--output',str(body),'--write-out','%{http_code}',url],capture_output=True)
rec={'url':url,'httpStatus':r.stdout.decode(),'curlExit':r.returncode,'startedAt':started,'retrievedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'bodySha256':sha(body) if body.exists() else None,'params':params,'scope':'FIRST_SIX_ISSUER_RESULTS_ENTRIES_ONLY_NOT_FULL_INVENTORY_OR_ABSENCE_PROOF','contractSources':[{'file':str(p),'sha256':sha(p)} for p in [parent,client,app]],'authenticationUsed':False,'accessControlBypassed':False};body.with_suffix('.json').write_text(json.dumps(rec,indent=2)+'\n');assert r.returncode==0 and rec['httpStatus']=='200'
module=text[text.index('74904:function'):text.index('43210:function',text.index('74904:function'))];assert 'AES.decrypt(t,e' in module and 'mode.ECB' in module and 'pad.Pkcs7' in module;key=re.search(r'Utf8.parse\("([^\"]+)"\)',module)[1].encode();result=subprocess.run(['openssl','enc','-d','-aes-192-ecb','-K',key.hex()],input=base64.b64decode(body.read_bytes()),capture_output=True);assert result.returncode==0;data=json.loads(result.stdout);out=B/'HDB-required-current-results-first-page-decoded.json';assert not out.exists();out.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n');out.with_suffix('.receipt.json').write_text(json.dumps({'method':'EXACT_PUBLIC_FRONTEND_RESPONSE_DECODER','sourceBodyFile':str(body),'sourceBodySha256':sha(body),'decoderModule':74904,'decoderSourceFile':str(app),'decoderSourceSha256':sha(app),'decodedBodySha256':sha(out),'decodedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'authenticationUsed':False,'accessControlBypassed':False},indent=2)+'\n');print(json.dumps({'httpStatus':rec['httpStatus'],'decodedBodySha256':sha(out),'dataType':type(data).__name__}))
